// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(w http.ResponseWriter, r *http.Request)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(w http.ResponseWriter, r *http.Request)
	// 取得本地维护屏障
	// (POST /v1/barriers)
	AcquireBarrier(w http.ResponseWriter, r *http.Request, params AcquireBarrierParams)
	// 释放已授权维护屏障
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(w http.ResponseWriter, r *http.Request, barrierId TypesIdentifier, params ReleaseBarrierParams)
	// 列入库任务
	// (GET /v1/builds)
	ListBuilds(w http.ResponseWriter, r *http.Request, params ListBuildsParams)
	// 人工或事件申请构建
	// (POST /v1/builds)
	CreateBuild(w http.ResponseWriter, r *http.Request, params CreateBuildParams)
	// 读取入库状态
	// (GET /v1/builds/{buildId})
	GetBuild(w http.ResponseWriter, r *http.Request, buildId Identifier, params GetBuildParams)
	// 取消入库链路
	// (POST /v1/builds/{buildId}/cancel)
	CancelBuild(w http.ResponseWriter, r *http.Request, buildId Identifier, params CancelBuildParams)
	// 返回安全诊断
	// (GET /v1/builds/{buildId}/diagnostics)
	RedactDiagnostics(w http.ResponseWriter, r *http.Request, buildId Identifier, params RedactDiagnosticsParams)
	// 读取文档索引视图
	// (POST /v1/document-index:read)
	ReadDocumentIndex(w http.ResponseWriter, r *http.Request, params ReadDocumentIndexParams)
	// 快速检索员有限核查
	// (POST /v1/evidence:inspect)
	InspectEvidence(w http.ResponseWriter, r *http.Request, params InspectEvidenceParams)
	// 读取索引配置
	// (GET /v1/index-config)
	ReadIndexConfig(w http.ResponseWriter, r *http.Request)
	// 更新索引配置
	// (PUT /v1/index-config)
	PutIndexConfig(w http.ResponseWriter, r *http.Request, params PutIndexConfigParams)
	// 读取知识管理真实选项
	// (GET /v1/index-options)
	ReadIndexOptions(w http.ResponseWriter, r *http.Request)
	// 读取原知识任务恢复证明
	// (POST /v1/jobs/{jobId}/recovery)
	ReadJobRecovery(w http.ResponseWriter, r *http.Request, jobId Identifier)
	// 统一生成并复用查询嵌入
	// (POST /v1/query-embeddings)
	CreateQueryEmbedding(w http.ResponseWriter, r *http.Request, params CreateQueryEmbeddingParams)
	// 估算全量重建费用
	// (POST /v1/rebuild-plans)
	EstimateRebuildPlan(w http.ResponseWriter, r *http.Request)
	// 批准全量重建
	// (POST /v1/rebuild-plans/{planId}:approve)
	ApproveRebuildPlan(w http.ResponseWriter, r *http.Request, planId string)
	// 统一混合检索
	// (POST /v1/retrievals)
	SearchKnowledge(w http.ResponseWriter, r *http.Request, params SearchKnowledgeParams)
	// 按引用读取证据片段
	// (POST /v1/sections:read)
	ReadSections(w http.ResponseWriter, r *http.Request, params ReadSectionsParams)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(w http.ResponseWriter, r *http.Request, snapshotId Identifier, params ReadSnapshotArchiveParams)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(w http.ResponseWriter, r *http.Request, params DiscardSnapshotParams)
	// 导出安全watermark快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(w http.ResponseWriter, r *http.Request, params ExportSnapshotParams)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(w http.ResponseWriter, r *http.Request, params StageSnapshotParams)
}

